//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.vScrenID = 'ULDBNS11101.xml';
scwin.vBndListProcsTpCd = "1";
scwin.vMktactCd = "202";
scwin.vBndApplId = '', scwin.vIsurCd = '', scwin.vIsurNm = '';
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetComboIsurNm
 * 설명       : 콤보데이터 정의 (그룹지정할 발행기관명)
 ***********************************************/
scwin.fn_SetComboIsurNm = function() {
    var dsNm = 'BNS_COM_CD';
    var qryId = 'lds.stf.bnschg.select.listGroupingIsurNmChg';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsurItem, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터 정의 (채권상장수수료면제사유코드)
 ***********************************************/
scwin.fn_SetComboCode = function() {
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_ListFeeExamptFsnCd, '03385');
};


/********************************************** 
 * 함수명   	: fn_list_sync
 * 설명       : 리스트 데이터를 조회한다.
 ***********************************************/
scwin.fn_list_sync = function() {
    var dsNm = 'BNS_GROUPPING_ISU_INFO';
    var qryId = 'lds.stf.bnschg.select.listSelectedIsurNmChg';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    param += '&{P}V_ISUR_CD=' + scwin.vIsurCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    var arrPnl = [pnl_NotAppoint];
    $c.bns.ShowWinArrPnl(arrPnl, grd_List1);
};


/********************************************** 
 * 함수명   	: fn_fee_sync
 * 설명       : 수수료 데이터를 조회한다.
 ***********************************************/
scwin.fn_fee_sync = function() {
    var dsNm = 'BNS_FEE_ANULFEE_INSERT_INFO';
    var qryId = 'lds.stf.bnschg.select.listSelectedIsurFee';
    var param = '&{P}V_ISUR_CD=' + scwin.vIsurCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_InputItem, dsNm, qryId, param);
};


/********************************************** 
 * 함수명		: fn_LeftCopy
 * 설명			: 그리드 행 복사 (좌 → 우)
 * argument	: String (One, All)
 ***********************************************/
scwin.fn_LeftCopy = function(Type) {
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        if ((Type == 'One') && (dts_List.RowMark(i) == 1)) {
            if (scwin.fn_CopyDuplCheck() == false) return;
            dts_CopyList.insertRow();
            for (var j = 1; j <= dts_List.getTotalCol(); j++) {
                dts_CopyList.setCellData(dts_CopyList.getRowPosition(), j, dts_List.getCellData(i, j));
            }
        }
        if ((Type == 'All')) {
            if (dts_CopyList.getTotalRow() != dts_List.getTotalRow()) {
                dts_CopyList.insertRow();
                for (var j = 1; j <= dts_List.getTotalCol(); j++) {
                    dts_CopyList.setCellData(i, j, dts_List.getCellData(i, j));
                }
            }
        }
    }
};






/********************************************** 
 * 함수명	: fn_CopyDuplCheck	
 * 설명		: 그리드 행 복사 시, 중복체크
 * return	: String
 ***********************************************/
scwin.fn_CopyDuplCheck = function() {
    var curRowVal = dts_List.getCellData(dts_List.getRowPosition(), "BND_APPL_ID");
    for (var i = 1; i <= dts_CopyList.getTotalRow(); i++) {
        if (curRowVal == dts_CopyList.getCellData(i, "BND_APPL_ID")) {
            $c.win.alert("이미 선택된 종목입니다.");
            return false;
        }
    }
};




/********************************************** 
 * 함수명		: fn_RightDel
 * 설명			: 그리드 행 제거
 * argument	: String (One, All)
 ***********************************************/
scwin.fn_RightDel = function(Type) {
    for (var i = 1; i <= dts_CopyList.getTotalRow(); i++) {
        if ((Type == 'All') || (Type == 'One') && (dts_CopyList.RowMark(i) == 1)) {
            if (Type == 'One') $c.cp.removeRow(dts_CopyList, dts_CopyList.getRowPosition());
            if (Type == 'All') dts_CopyList.removeAll();
        }
    }
};




/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function() {
    if (dts_CopyList.getTotalRow() == 0) {
        $c.win.alert("지정된 종목이 없습니다.");
        return false;
    }
    if ($c.stf.getObjectValue(txb_FeeGrpNm) == '') {
        $c.win.alert("[그룹명]을 입력하십시오.");
        txb_FeeGrpNm.focus();
        return;
    }
    //자리수 체크
    if (!$c.stf.checkMaxLength(txb_FeeGrpNm, 30, '그룹명')) return false;
    if (!$c.stf.checkMaxLength(txb_ChrgNm, 80, '담당자')) return false;
    if ($c.stf.getObjectValue(cmb_ChgListFeeFupayYn) == '') {
        $c.win.alert("[변경상장수수료 납부여부]를 선택하십시오.");
        cmb_ChgListFeeFupayYn.focus();
        return;
    }
    if ($c.stf.getObjectValue(cmb_ChgListFeeFupayYn) == "E" && $c.stf.getObjectValue(cmb_ListFeeExamptFsnCd) == '') {
        $c.win.alert("변경상장수수료 면제시에는 [면제사유]를 선택하십시오.");
        cmb_ListFeeExamptFsnCd.focus();
        return;
    }

    //면제가 아닐경우, 입금일 체크
    if ($c.stf.getObjectValue(cmb_ChgListFeeFupayYn) != "E") {
        if ($c.stf.getObjectValue(edt_FeeDepoDd) == '') {
            $c.win.alert("상장수수료 면제가 아닌 경우, 입금일을 입력하십시오.");
            return false;
        }
        if ($c.stf.getObjectValue(edt_FeeDepoDd) > scwin.vCurDate) {
            $c.win.alert("입금일은 오늘 이후 날짜를 입력하실 수 없습니다.");
            return false;
        }
    }
    return true;
};


/********************************************** 
 * 함수명		: fn_Insert
 * 설명			: 변경상장 수수료 등록
 ***********************************************/
scwin.fn_Insert = function() {
    //필수 입력 값 체크
    if (scwin.fn_InputCheck() == false) return;
    var vAnswer = confirm('변경상장수수료를 등록하시겠습니까?');
    if (vAnswer == true) {
        /*
			//필수 입력항목
			var vFeeGrpNm = getObjectValue(txb_FeeGrpNm);
			var vChgListFeeFupayYn = getObjectValue(cmb_ChgListFeeFupayYn);

			//비 필수 입력항목(공백처리)
			var vListFeeExamptFsnCd = getObjectValue(cmb_ListFeeExamptFsnCd);
			var vFeeDepoDd = getObjectValue(edt_FeeDepoDd);						
			var vChrgNm = getObjectValue(txb_ChrgNm);													

			//binding 되어 있지 않은 값들을 dts_InputItem에 저장
			dts_InputItem.AddRow();
dts_InputItem.setNameValue(1,"FEE_GRP_NM",vFeeGrpNm) ; 	//수수료그룹명
dts_InputItem.setNameValue(1,"CHG_LIST_FEE_FUPAY_YN",vChgListFeeFupayYn) ; 	//변경상장수수료완납여부
dts_InputItem.setNameValue(1,"BND_CHG_LIST_FEE_EXMPT_RSN_CD",vListFeeExamptFsnCd) ; 	//채권변경상장수수료면제사유코드
dts_InputItem.setNameValue(1,"FEE_DEPO_DD",vFeeDepoDd) ; 	//수수료입금일자
dts_InputItem.setNameValue(1,"CHRG_NM",vChrgNm) ; 	//담당자명
			*/

        var url = "/bns/ChgList.do?method=createGrpDesignFee";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.Action = $c.lc.fn_encodeNSession(url);
        trs_Save.KeyValue = "JSP(I:pInput=dts_InputItem, I:pInput2=dts_CopyList)";
        trs_Save.Post();
    }
};
scwin.gform_onload = function() {
    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Item);
    $c.bns.BnsPanelToGroupBox(pnl_Search);
    $c.bns.BnsPanelToGroupBox(pnl_Group);
    //BnsPanelToGroupBox(pnl_NotAppoint);
    //BnsPanelToGroupBox(pnl_Appoint);
    $c.bns.BnsPanelToGroupBox(pnl_Fee);

    //발행기관 조회
    scwin.fn_SetComboIsurNm();
    //면제사유코드
    scwin.fn_SetComboCode();

    //면제사유 비활성화
    cmb_ListFeeExamptFsnCd.setDisabled(true);

    //가우스헤더 셋팅(그리드 행 복사 대상)
    dts_CopyList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_GROUPPING_ISU_INFO";
    dts_CopyList.Reset();

    //가우스헤더 셋팅(입력항목)
    //dts_InputItem.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_FEE_ANULFEE_INSERT_INFO";
    //dts_InputItem.Reset();

};
scwin.dts_InputItem_OnLoadCompleted = function(rowcount) {
    //담당자명이 비어 있는 경우, 사용자 이름을 보여줌
    if ($c.stf.getObjectValue(txb_ChrgNm) == '') {
        $c.stf.setObjectValue(txb_ChrgNm, js_emp_nm);
    }
};
scwin.dts_IsurItem_OnLoadError = function() {
    $c.stf.alert_error(dts_IsurItem);
};
scwin.dts_IsurItem_OnLoadCompleted = function(rowcount) {
    dts_IsurItem.insertRow(dts_IsurItem.getRowPosition() - 1);
};
scwin.cmb_IsurNm_OnSelChange = function() {
    scwin.vIsurCd = cmb_IsurNm.BindColVal;
    scwin.fn_list_sync();
    scwin.fn_fee_sync();
    //dts_InputItem.Reset();

};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    var arrPnl = [pnl_NotAppoint];
    $c.bns.CloseWinArrPnl(rowcount, arrPnl, grd_List1);
    dts_CopyList.removeAll();
};
scwin.btn_ToRight_onclick = function() {
    scwin.fn_LeftCopy("One");
};
scwin.btn_ToRightAll_onclick = function() {
    dts_CopyList.removeAll();
    scwin.fn_LeftCopy("All");
};
scwin.btn_ToLeft_onclick = function() {
    scwin.fn_RightDel("One");
};
scwin.btn_ToLeftAll_onclick = function() {
    scwin.fn_RightDel("All");
    dts_InputItem.Reset();
};
scwin.img_FeeDepoDd_onclick = function() {
    popUpCalendar2(edt_FeeDepoDd);
};
scwin.cmb_ChgListFeeFupayYn_OnSelChange = function() {
    if ($c.stf.getObjectValue(cmb_ChgListFeeFupayYn) == "E") {
        cmb_ListFeeExamptFsnCd.setDisabled(true);
    } else {
        cmb_ListFeeExamptFsnCd.setDisabled(true);
        $c.stf.setObjectValue(cmb_ListFeeExamptFsnCd, '');
    }
};
scwin.btn_FeeReg_onclick = function() {
    scwin.fn_Insert();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.edt_ListFee_OnKillFocus = function() {
    edt_ListFee.RightMargin = 5;
};
